const SPRITES = Object.fromEntries(Object.entries(JRPG_VARIANTS).map(([name, dirs]) => [name, JRPG_GRIDS[dirs.front[0]]]));

// Disposable raster caches are shared across restarts, never saved with a floor.
function graphicsCache() {
  if (!state.art) state.art = { sprites: {}, tiles: {}, lights: {} };
  return state.art;
}

function graphicsSurface(width, height) {
  if (typeof document.createElement !== 'function') return null;
  const surface = document.createElement('canvas');
  surface.width = width; surface.height = height;
  return surface;
}

function spriteDimensions(name) {
  const grid = SPRITES[name];
  return { width: Math.max(...grid.map(row => row.length)) / ART_DENSITY, height: grid.length / ART_DENSITY };
}

function spriteFrameGrid(name, frame = 0, direction = 'front') {
  const dirs = JRPG_VARIANTS[name];
  const frames = dirs[direction] || dirs.front;
  return JRPG_GRIDS[frames[((frame % 4) + 4) % 4]];
}

function paintSprite(target, name, x = 0, y = 0, scale = 1, frame = 0, direction = 'front') {
  const grid = spriteFrameGrid(name, frame, direction), palette = SPRITE_PALETTES[name];
  for (let row = 0; row < grid.length; row++) for (let col = 0; col < grid[row].length; col++) {
    const color = palette[grid[row][col]];
    if (!color) continue;
    target.fillStyle = color;
    target.fillRect(x + col * scale, y + row * scale, scale, scale);
  }
}

function drawSprite(name, cx, cy, scale, frame = 0, direction = 'front') {
  const size = spriteDimensions(name), width = size.width * scale, height = size.height * scale;
  const x = Math.round(cx - width / 2), y = Math.round(cy - height / 2);
  const cache = graphicsCache().sprites;
  const key = direction !== 'front' ? `${name}:${direction}:${frame}` : frame ? `${name}:${frame}` : name;
  if (!cache[key]) {
    const surface = graphicsSurface(size.width * ART_DENSITY, size.height * ART_DENSITY);
    if (surface) { paintSprite(surface.getContext('2d'), name, 0, 0, 1, frame, direction); cache[key] = surface; }
  }
  if (cache[key]) {
    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(cache[key], x, y, width, height);
  } else {
    // Preserve the dependency-free no-DOM smoke harness.
    paintSprite(ctx, name, x, y, scale / ART_DENSITY, frame, direction);
  }
}

function drawEquipmentIcon(slot, item) {
  const name = item && SPRITES[item.sprite] ? item.sprite : { weapon: 'sword', armor: 'shield', ring: 'ring' }[slot];
  const target = document.getElementById(`${slot}Icon`).getContext('2d');
  target.clearRect(0, 0, 32, 32);
  const size = spriteDimensions(name), ratio = Math.min(28 / size.width, 28 / size.height);
  const cache = graphicsCache().sprites, key = `icon:${name}`;
  if (!cache[key]) {
    const surface = graphicsSurface(32, 32);
    if (surface) { paintSprite(surface.getContext('2d'), name, (32 - size.width * ratio) / 2, (32 - size.height * ratio) / 2, ratio / ART_DENSITY); cache[key] = surface; }
  }
  if (cache[key]) { target.imageSmoothingEnabled = false; target.drawImage(cache[key], 0, 0); }
  else paintSprite(target, name, (32 - size.width * ratio) / 2, (32 - size.height * ratio) / 2, ratio / ART_DENSITY);
}

function actorAnimationPose(name, actor) {
  const pose = { frame: 0, sx: 1, sy: 1, rise: 0, facing: 1 };
  if (!actor || typeof window.requestAnimationFrame !== 'function') return pose;
  const moving = actorIsMoving(actor), key = actorMotionKey(actor), time = state.motion.time;
  pose.facing = state.motion.facing[key] || 1;
  if (name === 'bat' || name === 'wasp' || name === 'dragonBoss') {
    pose.frame = Math.floor(time * 8 + (actor.id || 0) % 4) % 4;
    if (name === 'bat' || name === 'wasp') pose.rise = Math.sin(time * 8) * 0.8;
  } else if (name === 'mage' || name === 'healer' || ['hydra', 'medusa', 'darkWizard', 'skeletonKing'].includes(name)) {
    pose.frame = Math.floor(time * 6 + (actor.id || 0) % 4) % 4;
  } else if (moving && name === 'boar') {
    pose.sx = 1.08; pose.sy = 0.94; pose.rise = -Math.abs(Math.sin(time * Math.PI * 8)) * 3;
  } else if (moving && name === 'slime') {
    const progress = motionProgress(state.motion.moves[key]), hop = Math.sin(progress * Math.PI);
    pose.sx = 1.12 - hop * 0.18; pose.sy = 0.85 + hop * 0.25; pose.rise = -hop * 4;
  } else if (moving && name === 'mimic') {
    pose.rise = -Math.sin(motionProgress(state.motion.moves[key]) * Math.PI) * 2;
  } else if (moving) {
    pose.frame = Math.floor(time * 12) % 4;
    pose.rise = -Math.abs(Math.sin(time * Math.PI * 12)) * 0.7;
  }
  return pose;
}

function drawActorSprite(name, cx, cy, scale, actor = null) {
  const size = spriteDimensions(name), pose = actorAnimationPose(name,actor);
  const key=actor?actorMotionKey(actor):null;
  const direction=key && state.motion.directions ? state.motion.directions[key]||'front' : 'front';
  const directional=!!JRPG_VARIANTS[name][direction] && Object.keys(JRPG_VARIANTS[name]).length>1;
  const foot=size.height*scale/2;
  ctx.save();ctx.fillStyle='rgba(7,14,26,0.35)';ctx.beginPath();ctx.ellipse(cx,cy+foot-1,Math.min(24,size.width*scale*.3),Math.max(2,scale*1.5),0,0,Math.PI*2);ctx.fill();ctx.restore();
  ctx.save();ctx.translate(cx,cy+foot+pose.rise);ctx.scale(pose.sx*(directional?1:pose.facing),pose.sy);
  drawSprite(name,0,-foot,scale,pose.frame,directional?direction:'front');ctx.restore();
}

function drawDungeonTile(x, y) {
  const wall = state.map[y][x] === 1 && (state.area !== 'town' || !townSceneryTiles().has(`${x},${y}`));
  const front = wall && y + 1 < H && state.map[y + 1][x] !== 1;
  const variant = (x * 37 + y * 71) % 11;
  const biome = artBiomeAt(x,y);
  const accent = throneCarpetAt(x,y);
  const sand = biome === 'town' && !wall && ((y >= 28 && y <= 30) || (x >= 37 && x <= 40));
  const key = `${biome}:${wall ? 'wall' : 'floor'}:${front}:${variant}:${sand}:${x%6}:${y%6}:${accent}`;
  const cache = graphicsCache().tiles;
  if (!cache[key]) {
    const surface = graphicsSurface(TILE, TILE);
    if (surface) { paintDungeonTile(surface.getContext('2d'), wall, variant, front, biome, sand, x%6, y%6, accent); cache[key] = surface; }
  }
  if (cache[key]) {
    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(cache[key], x * TILE, y * TILE);
  } else {
    ctx.save(); ctx.translate(x * TILE, y * TILE); paintDungeonTile(ctx, wall, variant, front, biome, sand, x%6, y%6, accent); ctx.restore();
  }
  if (!wall) {
    ctx.fillStyle = 'rgba(13, 21, 40, 0.25)';
    if (y > 0 && state.map[y - 1][x] === 1) ctx.fillRect(x * TILE, y * TILE, TILE, 7);
    if (x > 0 && state.map[y][x - 1] === 1) ctx.fillRect(x * TILE, y * TILE, 5, TILE);
  }
}

function drawDungeonTorches() {
  const cache = graphicsCache().lights;
  const view = renderViewport();
  for (let y = view.y0; y < view.y1; y++) for (let x = view.x0; x < view.x1; x++) {
    if (!wallTorchAt(x, y)) continue;
    const cx = x * TILE + TILE / 2, cy = y * TILE + TILE / 2;
    const frame = environmentAnimationFrame(x, y);
    if (!cache.torch) {
      const surface = graphicsSurface(156, 156);
      if (surface) {
        const target = surface.getContext('2d');
        const glow = target.createRadialGradient(78, 78, 4, 78, 78, 78);
        glow.addColorStop(0, 'rgba(245,179,91,0.31)'); glow.addColorStop(0.45, 'rgba(218,139,51,0.19)'); glow.addColorStop(1, 'rgba(225,141,53,0)');
        target.fillStyle = glow; target.fillRect(0, 0, 156, 156); cache.torch = surface;
      }
    }
    if (cache.torch) {
      ctx.save(); ctx.globalAlpha = [0.94, 1, 0.88, 0.97][frame];
      ctx.drawImage(cache.torch, cx - 78, cy - 78); ctx.restore();
    }
    drawSprite('torch', cx, worldSpriteCenterY('torch',y,2), 2, frame);
  }
}

function wallTorchAt(x, y) {
  if (state.biome === 'town') return false;
  return state.map[y][x] === 1 && y + 1 < H && state.map[y + 1][x] !== 1 && (x * 7 + y * 13) % 6 === 0;
}

function environmentAnimationFrame(x, y) {
  return typeof window.requestAnimationFrame === 'function' ? Math.floor(state.motion.time * 9 + (x * 3 + y) % 4) % 4 : 0;
}

const TILE_PALETTES = {
  town: { floor:'#69764c', sand:'#ac9c73', wall:['#354c36','#496443','#718455'] },
  crypt: { floor:'#4e514b', wall:['#273534','#4d5850','#8b8d72'] },
  cavern: { floor:'#353e39', wall:['#27382f','#4d5949','#798066'] },
  kitchen: { floor:'#6d6652', wall:['#443f31','#735e45','#a88b5b'] },
  tavern: { floor:'#493f32', wall:['#594b35','#a99a75','#725a3f'] },
  throne: { floor:'#666b65', wall:['#273534','#4d5850','#8b8d72'] },
};

// Original JRPG material painters. World coordinates choose seams, never gameplay RNG.
function jrpgRect(c, x, y, w, h, color) { c.fillStyle = color; c.fillRect(Math.round(x), Math.round(y), Math.round(w), Math.round(h)); }
function jrpgPoly(c, points, color) {
  c.fillStyle = color; c.beginPath(); points.forEach(([x,y],i) => i ? c.lineTo(Math.round(x),Math.round(y)) : c.moveTo(Math.round(x),Math.round(y))); c.closePath(); c.fill();
}
function paintDungeonTile(c, wall, variant, front = false, biome = 'crypt', sand = false, tileX = 0, tileY = 0, accent = 0) {
  const n = variant, r = jrpgRect, material = TILE_PALETTES[biome] || TILE_PALETTES.crypt;
  if (biome === 'town') {
    if(wall){
      r(c,0,0,32,32,'#354c36');
      jrpgPoly(c,[[0,7],[5,3],[14,5],[21,1],[31,7],[32,28],[24,32],[16,29],[8,32],[0,25]],'#496443');
      r(c,4,7,10,2,'#718455');r(c,20,5,8,2,'#718455');r(c,2,24,28,4,'#293f32');return;
    }
    r(c,0,0,32,32,sand ? material.sand : material.floor);
    for (let i=0;i<18;i++) {
      const x=(i*13+n*3)%31, y=(i*7+n*11)%31;
      r(c,x,y,sand?1:3,1,sand?(i%2?'#cebb8a':'#968663'):(i%3?'#748153':'#617048'));
    }
    return;
  }
  if (wall) {
    const p = material.wall;
    r(c,0,0,32,32,p[1]);
    if(biome==='cavern') {
      jrpgPoly(c,[[0,6],[7,0],[24,3],[32,13],[26,31],[8,32]],p[0]);
      jrpgPoly(c,[[3,7],[9,2],[23,5],[29,14],[23,29],[7,28]],p[1]);
      r(c,8,3,15,2,p[2]);r(c,6,19,3,8,p[0]);
    } else if(biome==='tavern') {
      r(c,0,0,5,32,p[0]);jrpgPoly(c,[[5,0],[9,0],[31,29],[31,32],[27,32]],p[2]);r(c,0,29,32,3,p[0]);
    } else {
      r(c,0,0,32,2,p[2]);r(c,0,15,32,2,p[0]);r(c,n%2?10:21,2,2,13,p[0]);r(c,n%2?23:8,17,2,15,p[0]);r(c,3,4,20,1,biome==='kitchen'?'#a18359':'#6b7160');
    }
    if(front){r(c,0,2,32,4,p[2]);r(c,0,6,32,3,p[0]);r(c,0,29,32,3,p[0]);}
    return;
  }
  const ox=tileX*32, oy=tileY*32;
  c.save();c.beginPath();c.rect(0,0,32,32);c.clip();c.translate(-ox,-oy);
  if(biome==='cavern') {
    r(c,ox,oy,32,32,'#353e39');
    for(let y=Math.floor(oy/24)*24-24;y<oy+56;y+=24)for(let x=Math.floor(ox/48)*48-48;x<ox+80;x+=48){
      const xx=x+(Math.abs(Math.floor(y/24))%2)*24;
      jrpgPoly(c,[[xx+4,y+3],[xx+32,y],[xx+46,y+10],[xx+40,y+22],[xx+10,y+23],[xx,y+13]],Math.abs(x/48+y/24)%2?'#434d43':'#3d473e');
      r(c,xx+9,y+5,19,1,'#536052');
    }
  } else if(biome==='kitchen') {
    r(c,ox,oy,32,32,'#6d6652');
    for(let y=Math.floor(oy/24)*24;y<oy+32;y+=24)for(let x=Math.floor(ox/24)*24;x<ox+32;x+=24){r(c,x+1,y+1,23,23,((x+y)/24)%2?'#b3ab88':'#8d8d73');r(c,x+2,y+2,20,1,'#c6ba94');}
  } else if(biome==='tavern') {
    r(c,ox,oy,32,32,'#493f32');
    for(let y=oy;y<oy+32;y+=16){r(c,ox,y+1,32,15,(Math.floor(y/16)+Math.floor(ox/96))%2?'#806345':'#70583d');r(c,ox,y+2,32,1,'#a28252');r(c,ox+(Math.floor(y/16)%2?16:0),y+2,1,13,'#493f32');r(c,ox+7,y+9,17,1,'#655037');}
  } else if(biome==='throne') {
    r(c,ox,oy,32,32,'#666b65');r(c,ox+1,oy+1,31,31,(tileX+tileY)%2?'#7d867b':'#acaf99');
    jrpgPoly(c,[[ox+3,oy+8],[ox+16,oy+13],[ox+19,oy+24],[ox+30,oy+28],[ox+19,oy+26],[ox+15,oy+15]],'#919a86');
  } else {
    r(c,ox,oy,32,32,'#3d423e');
    for(let y=Math.floor(oy/24)*24;y<oy+32;y+=24)for(let x=Math.floor(ox/48)*48-48;x<ox+80;x+=48){const xx=x+(Math.abs(Math.floor(y/24))%2)*24;r(c,xx+1,y+1,46,22,['#4e514b','#55564c','#494d47','#5b5b50'][Math.abs(Math.floor(xx/48)+Math.floor(y/24))%4]);r(c,xx+2,y+2,44,1,'#68685a');}
  }
  c.restore();
  if(biome==='throne' && accent){
    r(c,0,0,32,32,'#743e3d');
    if(accent===1)r(c,2,0,2,32,'#c5a264');
    if(accent===3)r(c,28,0,2,32,'#c5a264');
    if(accent===2)jrpgPoly(c,[[12,10],[20,10],[26,16],[20,22],[12,22],[6,16]],'#a07950');
  }
}

function artBiomeAt(x,y){
  if(state.area==='town')return 'town';
  const room=state.depth===50 && state.rooms.find(r=>r.isThroneRoom);
  return room && x>=room.x && x<room.x+room.w && y>=room.y && y<room.y+room.h ? 'throne' : state.biome||'crypt';
}
function throneCarpetAt(x,y){
  const room=state.depth===50 && state.rooms.find(r=>r.isThroneRoom);
  return room && x>=room.cx-1 && x<=room.cx+1 && y>room.y && y<room.y+room.h-1 ? x-room.cx+2 : 0;
}

function drawDungeonWallFaces() {
  if (state.area === 'town') return;
  const view=renderViewport(), cache=graphicsCache().tiles;
  for(let y=view.y0;y<Math.min(H,view.y1+1);y++)for(let x=view.x0;x<view.x1;x++){
    if(!state.visited.has(`${x},${y}`) || state.map[y][x]!==1 || y+1>=H || state.map[y+1][x]!==0)continue;
    const biome=artBiomeAt(x,y), key=`face:${biome}:${(x+y)%2}`;
    if(!cache[key]){const s=graphicsSurface(32,48);if(s){paintWallFace(s.getContext('2d'),biome,(x+y)%2);cache[key]=s;}}
    if(cache[key])ctx.drawImage(cache[key],x*TILE,(y+1)*TILE-48);
    else{ctx.save();ctx.translate(x*TILE,(y+1)*TILE-48);paintWallFace(ctx,biome,(x+y)%2);ctx.restore();}
  }
}
function paintWallFace(c,biome,n){
  const r=jrpgRect;
  r(c,0,0,32,48,biome==='cavern'?'#354939':biome==='kitchen'?'#735e45':biome==='tavern'?'#a99a75':'#4d5850');
  if(biome==='cavern') {jrpgPoly(c,[[0,7],[8,0],[25,4],[32,19],[24,47],[6,48]],'#4d5949');jrpgPoly(c,[[7,2],[11,3],[4,23],[9,43],[6,45],[1,23]],'#798066');}
  else if(biome==='tavern'){r(c,0,0,4,48,'#594b35');jrpgPoly(c,[[5,0],[9,0],[32,34],[32,40]],'#725a3f');}
  else{for(let y=8;y<48;y+=12){r(c,0,y,32,1,'#273534');r(c,(n+(y/12|0))%2?10:23,y+1,2,11,'#303c37');r(c,3,y+2,21,1,biome==='kitchen'?'#a18359':'#6b7160');}}
  r(c,0,0,32,5,biome==='tavern'?'#5b4d36':biome==='kitchen'?'#a88b5b':'#8b8d72');r(c,1,1,30,1,'#b0ad8b');r(c,0,45,32,3,'#27352d');
}
